  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt);
\node[left] at (O) {$O$};
\coordinate (A) at (-1.147,1.638);
\coordinate (B) at (1.147,1.638);
\coordinate (E) at (0,1.638);
\coordinate (C) at (1.812,-0.844);
\coordinate (D) at (-0.174,-1.992);
\coordinate (F) at (0.819,-1.418);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[right] at (C) {$C$};
\node[below left] at (D) {$D$};
\draw[tickmark2] (A) -- (B);
\draw[tickmark2] (C) -- (D);
