\draw (Fa) -- ($(Fa)+(Fb)-(F)$) -- (Fb);
\end{tikzpicture}
[/tikz]

The perpendicular from the centre to a chord bisects the chord, and the perpendicular bisector of a chord passes through the centre.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt);
\node[left] at (O) {$O$};
\coordinate (A) at (1.2,1.6);
\coordinate (B) at (1.2,-1.6);
\coordinate (M) at (1.2,0);
\node[above] at (A) {$A$};
\node[below] at (B) {$B$};
\node[right] at (M) {$M$};
\draw[tickmark] (A) -- (M);
