\coordinate (Ma) at ($(M)!0.3cm!(A)$);
\coordinate (Mb) at ($(M)!0.3cm!(O)$);
\draw (Ma) -- ($(Ma)+(Mb)-(M)$) -- (Mb);
\end{tikzpicture}
[/tikz]

