\draw (0,-1)--(0.2,-1)--(0.2,-1.2);
\fill (O) circle (1.2pt); \node[above] at (O) {$O$}; \node[below left] at (A) {$A$}; \node[below right] at (B) {$B$}; \node[below] at (M) {$M$};
\node[left] at (-0.8,-0.6) {$20\text{ cm}$}; \draw[<->] (-1.6,-2.35)--(1.6,-2.35) node[midway,below] {$32\text{ cm}$};
\end{tikzpicture}
[/tikz]

Circles with centres $P$ and $Q$ intersect at $A$ and $B$. The line $PQ$ meets $AB$ at $M$, between the centres. Given $PA=17$ cm, $AB=30$ cm and $QM=20$ cm, find $QA$ and $PQ$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (-0.8,0); \coordinate (Q) at (2,0); \coordinate (M) at (0,0); \coordinate (A) at (0,1.5); \coordinate (B) at (0,-1.5);
\draw (P) circle (1.7); \draw (Q) circle (2.5); \draw (P)--(Q) (A)--(B) (P)--(A)--(Q);
\fill (P) circle (1.2pt); \fill (Q) circle (1.2pt); \node[below left] at (P) {$P$}; \node[below right] at (Q) {$Q$}; \node[above right,xshift=3pt,yshift=3pt] at (M) {$M$}; \node[above] at (A) {$A$}; \node[below] at (B) {$B$};
\node[above left] at (-0.4,0.75) {$17\text{ cm}$}; \node[below] at (1,0) {$20\text{ cm}$};
\draw[<->] (-2.8,-1.5)--(-2.8,1.5) node[midway,left] {$30\text{ cm}$};
\end{tikzpicture}
[/tikz]

A circle has centre $O$, and $OM\perp AB$ at $M$. Prove that $\triangle OAM\equiv\triangle OBM$, hence prove that $AM=BM$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0); \coordinate (A) at (-1.6,-1.2); \coordinate (B) at (1.6,-1.2); \coordinate (M) at (0,-1.2);
\draw (O) circle (2); \draw (O)--(A)--(B)--(O) (O)--(M); \draw (0,-1)--(0.2,-1)--(0.2,-1.2);
